parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "type": {
      "type": "string",
      "enum": ["Bug", "Tâche", "none"],
      "description": "Bug pour un défaut, Tâche pour une idée d'amélioration, none si aucun ticket n'est nécessaire"
    },
    "product": {
      "type": "string",
      "enum": ["NovaCRM", "NovaPay", "NovaPlanning", "NovaDesk", "Autre"],
      "description": "Produit concerné, Autre si ce n'est aucun des quatre"
    },
    "summary": {
      "type": "string",
      "minLength": 1,
      "maxLength": 80,
      "description": "Résumé court du problème ou de l'idée, sans le nom du produit, sur une seule ligne"
    },
    "description": {
      "type": "string",
      "minLength": 1,
      "maxLength": 1000,
      "description": "Pour l'équipe de dev, en 2 à 4 phrases : ce qui se passe (ou ce qui est demandé), où dans le produit et qui est touché ; reformulé, jamais copié de l'email"
    },
    "steps": {
      "type": "array",
      "maxItems": 10,
      "items": { "type": "string", "minLength": 1, "maxLength": 200 },
      "description": "Bug : les étapes pour reproduire, une action courte par étape, tirées de l'email ; liste vide si l'email n'en donne pas ou pour une Tâche"
    },
    "expected": {
      "type": "string",
      "minLength": 1,
      "maxLength": 400,
      "description": "Bug : le comportement attendu ; Tâche : le besoin et le résultat souhaité"
    },
    "impact": {
      "type": "string",
      "minLength": 1,
      "maxLength": 400,
      "description": "Qui est touché, à quel point, et le contournement s'il en existe un"
    },
    "priority": {
      "type": "string",
      "enum": ["Highest", "High", "Medium", "Low", "Lowest"],
      "description": "Priorité Jira"
    },
    "label": {
      "type": "string",
      "enum": ["back", "front"],
      "description": "back pour le serveur et les données, front pour l'interface"
    },
    "confidence": {
      "type": "string",
      "enum": ["high", "low"],
      "description": "low si tu hésites sur le type ou sur le besoin d'un ticket, sinon high"
    },
    "reason": {
      "type": "string",
      "minLength": 1,
      "maxLength": 200,
      "description": "Une phrase qui explique ton choix, surtout ce qui te fait hésiter"
    }
  },
  "required": ["type", "product", "summary", "description", "steps", "expected", "impact", "priority", "label", "confidence", "reason"],
  "additionalProperties": false
}
